// Extension d'essai de l'outil interactif (protocole 1.0, lot 6) : un trait entre deux points, avec son aperçu.
let depart = null;
let vise = null;
const ecart = (a, b) => Math.hypot(b[0] - a[0], b[1] - a[1], b[2] - a[2]);
const repos = (en) => ({ etat: en ? "Click the start point." : "Cliquez le point de départ.", curseur: "croix" });
// Description de l'aperçu : la Planche la dessine, l'outil ne dessine rien lui-même.
const enCours = async (en) => {
  const texte = await planche.unites.formater(ecart(depart, vise));
  const milieu = [(depart[0] + vise[0]) / 2, (depart[1] + vise[1]) / 2, (depart[2] + vise[2]) / 2];
  return {
    apercu: { pointilles: [[depart, vise]], points: [depart], textes: [{ point: milieu, texte }] },
    etat: en ? "Click the end point, or type a length. | Esc = Cancel." : "Cliquez le point d'arrivée, ou saisissez une longueur. | Échap = Annuler.",
    saisie: { libelle: en ? "Length" : "Longueur", valeur: texte },
    reference: depart,
    curseur: "cible",
  };
};
const recommencer = (d) => {
  depart = null;
  vise = null;
  return repos(d.langue === "en");
};
planche.outil.sur("trait", "activation", recommencer);
planche.outil.sur("trait", "annulation", recommencer);
planche.outil.sur("trait", "deplacement", (d) => {
  if (!depart) return null;
  vise = d.point;
  return enCours(d.langue === "en");
});
planche.outil.sur("trait", "clic", async (d) => {
  if (!depart) {
    depart = d.point;
    vise = d.point;
    return enCours(d.langue === "en");
  }
  if (ecart(depart, d.point) < 1e-6) return null;
  await planche.modele.ligne(depart, d.point);
  return recommencer(d);
});
// Longueur saisie : le trait part du point de départ, vers le point visé.
planche.outil.sur("trait", "saisie", async (d) => {
  const l = depart && vise ? ecart(depart, vise) : 0;
  if (!(d.longueur > 0) || l < 1e-9) return null;
  const k = d.longueur / l;
  await planche.modele.ligne(depart, [depart[0] + (vise[0] - depart[0]) * k, depart[1] + (vise[1] - depart[1]) * k, depart[2] + (vise[2] - depart[2]) * k]);
  return recommencer(d);
});
